        len as int % page_size() == 0,

        old(mem).wf(),
        old(mem).os_exact_range(addr as int, len as int),
        old(mem).has_pointsto_for_all_read_write(),
        old(mem).points_to.provenance() == addr@.provenance,
    ensures
